local names = { peripheral.getNames() }
local devices = {}
for _, name in ipairs(names) do
  local ok, dev = pcall(peripheral.wrap, name)
  if ok and dev then
    table.insert(devices, { name = name, type = peripheral.getType(name) or "unknown" })
  end
end
return { peripherals = devices, count = #devices }
